import React, {useContext} from "react";
import "./Skills.scss";
import SoftwareSkill from "../../components/softwareSkills/SoftwareSkill";
import {illustration, skillsSection} from "../../portfolio";
import {Fade} from "react-reveal";
import codingPerson from "../../assets/lottie/codingPerson";
import DisplayLottie from "../../components/displayLottie/DisplayLottie";
import StyleContext from "../../contexts/StyleContext";

export default function Skills() {
  const {isDark} = useContext(StyleContext);
  if (!skillsSection.display) {
    return null;
  }
  return (
    <div className={isDark ? "dark-mode main" : "main"} id="skills">
      <div className="skills-header">
        <Fade bottom duration={1000}>
          <h1 className="skills-heading">{skillsSection.title}</h1>
        </Fade>
      </div>
      <div className="skills-container">
        <Fade bottom duration={1200} cascade>
          <div className="skills-grid">
            {skillsSection.skills.map((skill, i) => {
              const icons = [
                {name: "react", class: "fab fa-react", color: "#61dafb"},
                {name: "nodejs", class: "fab fa-node-js", color: "#68a063"},
                {name: "python", class: "fab fa-python", color: "#3776ab"},
                {name: "figma", class: "fab fa-figma", color: "#f24e1e"}
              ];
              return (
                <div key={i} className="skill-glass-card">
                  <div className="card-content">
                    <h3 className="skill-card-title">{skill.split(" (")[0]}</h3>
                    <p className="skill-card-desc">
                      {skill.split(" (")[1]?.replace(")", "")}
                    </p>
                    <div className="skill-icons">
                      {icons.slice(i, i + 2).map((icon, idx) => (
                        <i
                          key={idx}
                          className={icon.class}
                          style={{color: icon.color}}
                        ></i>
                      ))}
                    </div>
                  </div>
                  <div className="glass-reflection"></div>
                </div>
              );
            })}
          </div>
        </Fade>
      </div>
    </div>
  );
}
